use std::{error::Error, fs};
use tree_sitter::{Node, Parser};
fn named(node: Node) -> Vec<Node> {
    let mut cursor = node.walk();
    node.named_children(&mut cursor).collect()
}
fn main() -> Result<(), Box<dyn Error>> {
    let src = fs::read("hello.ws")?;
    let mut parser = Parser::new();
    parser.set_language(tree_sitter_witcherscript::language())?;
    let tree = parser.parse(&src, None).ok_or("missing syntax tree")?;
    let root = tree.root_node();
    if root.has_error() {
        return Err(format!("the original script has diagnostics: {}", root.to_sexp()).into());
    }
    let root_children=named(root);
    if root_children.len()!=1 { return Err("expected one top-level function".into()); }
    let function=root_children[0];
    println!("Native tree: {}", function.to_sexp());
    let name=function.child_by_field_name("name").ok_or("missing function name")?;
    let declared=function.child_by_field_name("return_type").ok_or("missing typed return")?;
    let definition=function.child_by_field_name("definition").ok_or("missing function body")?;
    if name.utf8_text(&src)?!="CorpusGreeting" || declared.utf8_text(&src)?!="string" {
        return Err("unexpected callable contract".into());
    }
    let body=named(definition);
    if body.len()!=1 || body[0].kind()!="return_stmt" { return Err("unexpected control flow".into()); }
    let result=named(body[0]);
    if result.len()!=1 || !result[0].kind().contains("string") {
        return Err("return does not evaluate to its declared string type".into());
    }
    let value: String = serde_json::from_str(result[0].utf8_text(&src)?)?;
    println!("Typed return: {value}");
    Ok(())
}
